// n8n Code Node
const input = $input.first().json.body.location; // e.g., "next to player Mauri67"

function parseLocation(input) {
    const coordMatch = input.match(/^(-?\d+\.?\d*)\s*[,\s]\s*(-?\d+\.?\d*)\s*[,\s]\s*(-?\d+\.?\d*)$/);
    if (coordMatch) {
        return {
            type: 'coordinates',
            x: parseFloat(coordMatch[1]),
            y: parseFloat(coordMatch[2]),
            z: parseFloat(coordMatch[3])
        };
    }

    const playerMatch = input.match(/(?:next\s+to\s+)?player\s+(\w+)/i);
    if (playerMatch) {
        return {
            type: 'player',
            name: playerMatch[1]
        };
    }

    return {
        type: 'landmark',
        name: input.trim()
    };
}

const location = parseLocation(input);
return { location };

const status = $json;
return {
  Position: {
    x: Math.floor(status.position?.x || 0),
    y: Math.floor(status.position?.y || 64),
    z: Math.floor(status.position?.z || 0)
  }
}

// Convert taskDivision into STAGES (Dictionary format)
// Stages keyed by stage number, Tasks keyed by worker name
// Dynamically handles ANY number of workers - no hardcoding

const buildLocation = $('Reserve Location').first().json.buildLocation;
const taskDivision = $('Webhook').first().json.body.taskDivision;
const workers = $('Webhook').first().json.body.workers;

// Parse build Request
const buildRequest = $('Webhook').first().json.body.buildRequest;
const dimensionMatch = buildRequest.match(/(\d+)\s*x\s*(\d+)/i);
const houseWidth = dimensionMatch ? parseInt(dimensionMatch[1]) : 9;  // default 9
const houseDepth = dimensionMatch ? parseInt(dimensionMatch[2]) : 7;

const houseX = buildLocation.x;
const houseY = buildLocation.y;
const houseZ = buildLocation.z;

// Calculate footprint boundaries as per request
// Calculate footprint from actual dimensions
const footprintMinX = Math.floor(houseX - houseWidth / 2);
const footprintMaxX = Math.floor(houseX + (houseWidth - 1) / 2);

const footprintMinZ = Math.floor(houseZ - houseDepth / 2);
const footprintMaxZ = Math.floor(houseZ + (houseDepth - 1) / 2);

const floorY = houseY;
const wallHeight = 3;
const maxY = houseY + wallHeight;

const workerNames = Object.keys(taskDivision);
const numWorkers = workerNames.length;
const footprintWidth = footprintMaxX - footprintMinX + 1; // 7

console.log(`House footprint: x:${footprintMinX} to ${footprintMaxX}, z:${footprintMinZ} to ${footprintMaxZ}, y:${floorY} to ${maxY}`);
console.log(`Number of workers: ${numWorkers}`);

// Dynamically determine worker x-ranges (split footprint equally)
const workerRanges = {};
const blocksPerWorker = footprintWidth / numWorkers;

workerNames.forEach((workerName, index) => {
  const rangeStart = footprintMinX + Math.floor(index * blocksPerWorker);
  const rangeEnd = footprintMinX + Math.floor((index + 1) * blocksPerWorker) - 1;

  workerRanges[workerName] = { 
    xMin: rangeStart, 
    xMax: rangeEnd,
    index: index
  };

  console.log(`${workerName} (${index + 1}/${numWorkers}): x:${rangeStart} to ${rangeEnd}`);
});

// Build stages as DICTIONARY (keyed by stage number)
const stages = {};
const maxSubtasks = Math.max(...Object.values(taskDivision).map(t => t.subtasks.length));

for (let stageNum = 0; stageNum < maxSubtasks; stageNum++) {
  const stageTasks = {}; // Dictionary with worker names as keys
  let hasWorkers = false;

  workerNames.forEach((workerName) => {
    const taskObj = taskDivision[workerName];
    const range = workerRanges[workerName];

    if (stageNum >= taskObj.subtasks.length) {
      return; // This worker doesn't have this stage
    }

    hasWorkers = true;
    const subtask = taskObj.subtasks[stageNum];

    // Replace placeholder coordinates with absolute coordinates
    let updatedSubtask = subtask
      .replace(/x:\s*minX\s*to\s*midX/gi, `x:${range.xMin} to ${range.xMax}`)
      .replace(/x:\s*midX\s*to\s*maxX/gi, `x:${range.xMin} to ${range.xMax}`)
      .replace(/x:\s*minX\s*to\s*maxX/gi, `x:${footprintMinX} to ${footprintMaxX}`)
      .replace(/z:\s*minZ\s*to\s*maxZ/gi, `z:${footprintMinZ} to ${footprintMaxZ}`)
      .replace(/height.*\(e\.g\.,\s*\d+\s*blocks?\s*tall\)/gi, `height (${wallHeight} blocks tall)`)
      .replace(/\b3\s*blocks?\s*tall\b/gi, `${wallHeight} blocks tall`)
      .replace(/midX/g, `${range.xMax}`)
      .replace(/midline/g, `midline at x:${range.xMax}`)
      .replace(/minX/g, `${footprintMinX}`)
      .replace(/maxX/g, `${footprintMaxX}`)
      .replace(/minZ/g, `${footprintMinZ}`)
      .replace(/maxZ/g, `${footprintMaxZ}`);

    // Find worker port from workers array
    const workerData = workers.find(w => w.workerName === workerName);
    const port = workerData ? workerData.port : null;

    if (!port) {
      console.warn(`Warning: No port found for ${workerName}`);
      return;
    }

    // Determine boundary messages based on worker position
    let boundaryMsg = '';
    const nextWorkerIndex = range.index + 1;
    const prevWorkerIndex = range.index - 1;

    if (nextWorkerIndex < numWorkers) {
      const nextWorkerName = workerNames[nextWorkerIndex];
      boundaryMsg += `- Right boundary (shared with ${nextWorkerName}): x:${range.xMax}\n`;
    }
    if (prevWorkerIndex >= 0) {
      const prevWorkerName = workerNames[prevWorkerIndex];
      boundaryMsg += `- Left boundary (shared with ${prevWorkerName}): x:${range.xMin}\n`;
    }

    // Build full prompt for this stage/worker
    const fullPrompt = `${taskObj.objective}

STAGE ${stageNum + 1} OF ${taskObj.subtasks.length}:
${updatedSubtask}

ABSOLUTE COORDINATES FOR THIS WORKER:
- X range: ${range.xMin} to ${range.xMax}
- Z range: ${footprintMinZ} to ${footprintMaxZ}
- Y range: ${floorY} to ${maxY}
${boundaryMsg}
House center: (${houseX}, ${houseY}, ${houseZ})

Scope: ${taskObj.scope}

Constraints: ${taskObj.constraints}
- Stay within x:${range.xMin} to ${range.xMax}
- Coordinate with other workers at shared boundaries

Work together with nearby workers to create a cohesive structure.`;

    // Add task to stageTasks dictionary with worker name as key
    stageTasks[workerName] = {
      stageNumber: stageNum + 1,
      totalStages: taskObj.subtasks.length,
      worker: workerName,
      port: port,
      status: "not-started",
      subtask: updatedSubtask,
      objective: taskObj.objective,
      coordinates: {
        xMin: range.xMin,
        xMax: range.xMax,
        zMin: footprintMinZ,
        zMax: footprintMaxZ,
        yMin: floorY,
        yMax: maxY
      },
      fullPrompt: fullPrompt,
      completionTime: null,
      result: null
    };
  });

  // Only add stage if it has workers
  if (hasWorkers) {
    const stageKey = (stageNum + 1).toString();
    stages[stageKey] = {
      stageNumber: stageNum + 1,
      status: "not-started",
      tasks: stageTasks
    };
  }
}

console.log(`Generated ${Object.keys(stages).length} stages`);
Object.keys(stages).forEach(stageKey => {
  const stage = stages[stageKey];
  console.log(`Stage ${stage.stageNumber}: ${Object.keys(stage.tasks).join(", ")} [${stage.status}]`);
});

return { 
  stages: stages,
  totalStages: Object.keys(stages).length,
  houseInfo: {
    center: { x: houseX, y: houseY, z: houseZ },
    footprint: `${footprintMaxX - footprintMinX + 1}x${footprintMaxZ - footprintMinZ + 1}`,
    boundaries: { 
      xMin: footprintMinX, 
      xMax: footprintMaxX, 
      zMin: footprintMinZ, 
      zMax: footprintMaxZ, 
      floorY: floorY, 
      maxY: maxY 
    },
    workers: Object.keys(workerRanges).map(name => ({
      name: name,
      xRange: `${workerRanges[name].xMin} to ${workerRanges[name].xMax}`
    }))
  }
};

// Convert taskDivision placeholder coordinates (minX, midX, maxX, minZ, maxZ) to absolute

const buildLocation = $('Teleport Workers').first().json.buildLocation;
const taskDivision = $('Webhook').first().json.body.taskDivision;

const houseX = buildLocation.x;
const houseY = buildLocation.y;
const houseZ = buildLocation.z;

// 7x7 footprint centered at houseX, houseZ
const minX = Math.floor(houseX - 3);
const maxX = Math.floor(houseX + 3);
const midX = Math.floor(houseX);

const minZ = Math.floor(houseZ - 3);
const maxZ = Math.floor(houseZ + 3);

const floorY = houseY;
const wallHeight = 3;
const maxY = houseY + wallHeight;

console.log(`House footprint: x:${minX} to ${maxX}, z:${minZ} to ${maxZ}, y:${floorY} to ${maxY}`);
console.log(`Midline: x:${midX}`);

const updatedTasks = {};

Object.keys(taskDivision).forEach((workerName) => {
  const taskObj = taskDivision[workerName];

  // Determine this worker's x-range
  let workerXMin, workerXMax;
  if (workerName === "Worker1") {
    workerXMin = minX;
    workerXMax = midX;
  } else if (workerName === "Worker2") {
    workerXMin = midX;
    workerXMax = maxX;
  }

  console.log(`${workerName}: x:${workerXMin} to ${workerXMax}`);

  // ========== RECONSTRUCT TASK STRING WITH ABSOLUTE COORDINATES ==========
  let taskString = `${taskObj.objective}

Scope: ${taskObj.scope}
ABSOLUTE COORDINATES - x:${workerXMin} to ${workerXMax}, z:${minZ} to ${maxZ}, y:${floorY} to ${maxY}.
Your working region: x:${workerXMin} to ${workerXMax}.

Subtasks:
${taskObj.subtasks.map((s, i) => {
  // Replace placeholder coordinates in each subtask
  let updatedSubtask = s
    .replace(/x:\s*minX\s*to\s*midX/gi, `x:${workerXMin} to ${workerXMax}`)
    .replace(/x:\s*midX\s*to\s*maxX/gi, `x:${workerXMin} to ${workerXMax}`)
    .replace(/x:\s*minX\s*to\s*maxX/gi, `x:${minX} to ${maxX}`)
    .replace(/z:\s*minZ\s*to\s*maxZ/gi, `z:${minZ} to ${maxZ}`)
    .replace(/height.*\(e\.g\.,\s*\d+\s*blocks\s*tall\)/gi, `height (${wallHeight} blocks tall)`)
    .replace(/3\s*blocks?\s*tall/gi, `${wallHeight} blocks tall`)
    .replace(/midX/g, `x:${midX}`)
    .replace(/midline/g, `midline at x:${midX}`)
    .replace(/minX/g, `${minX}`)
    .replace(/maxX/g, `${maxX}`)
    .replace(/minZ/g, `${minZ}`)
    .replace(/maxZ/g, `${maxZ}`);

  return `${i + 1}. ${updatedSubtask}`;
}).join('\n')}

Block Break Limit: ${taskObj.blockBreakLimit}

Assumptions: ${taskObj.assumptions}

Constraints: ${taskObj.constraints}
- Do NOT build outside x:${workerXMin} to ${workerXMax}

CRITICAL: Use ABSOLUTE coordinates x:${workerXMin} to ${workerXMax}, z:${minZ} to ${maxZ}, y:${floorY} to ${maxY}.
House center: (${houseX}, ${houseY}, ${houseZ})
${workerName === "Worker1" ? `Your right boundary: x:${midX}` : `Your left boundary: x:${midX}`}

Work together with nearby workers to create a cohesive structure. Position yourself strategically to connect your work with others.`;

  updatedTasks[workerName] = taskString;
});

return updatedTasks;
